-- =====================================================================
-- Borealis Bank of Canada (FICTIONAL) - core banking OLTP database
-- All rows are synthetic and generated by poc/toolbox/poc/generate_data.py
-- Comments intentionally left sparse in places: undocumented / ambiguous
-- columns are part of the test (can OpenMetadata still find the PI?).
-- =====================================================================

CREATE SCHEMA core;      -- system of record: customers, accounts, transactions
CREATE SCHEMA kyc;       -- know-your-customer / identity verification (FINTRAC)
CREATE SCHEMA ops;       -- operational / legacy tables

-- ---------------------------------------------------------------- core
CREATE TABLE core.branch (
    branch_id       SERIAL PRIMARY KEY,
    transit_number  CHAR(5)      NOT NULL UNIQUE,
    branch_name     VARCHAR(80)  NOT NULL,
    city            VARCHAR(60)  NOT NULL,
    province        CHAR(2)      NOT NULL
);

CREATE TABLE core.customer (
    customer_id     BIGSERIAL PRIMARY KEY,
    first_name      VARCHAR(60)  NOT NULL,
    last_name       VARCHAR(60)  NOT NULL,
    date_of_birth   DATE         NOT NULL,
    sin             CHAR(11),                    -- Social Insurance Number, NNN-NNN-NNN
    email           VARCHAR(120),
    phone_number    VARCHAR(20),
    street_address  VARCHAR(120),
    city            VARCHAR(60),
    province        CHAR(2),
    postal_code     CHAR(7),
    occupation      VARCHAR(80),
    annual_income   NUMERIC(12,2),
    preferred_language CHAR(2)   DEFAULT 'en',
    customer_status VARCHAR(10)  NOT NULL DEFAULT 'ACTIVE',  -- ACTIVE | CLOSED
    created_at      TIMESTAMP    NOT NULL,
    closed_at       TIMESTAMP
);

-- PIPEDA Principle 4.3 (Consent): one row per customer per purpose.
CREATE TABLE core.customer_consent (
    consent_id      BIGSERIAL PRIMARY KEY,
    customer_id     BIGINT       NOT NULL REFERENCES core.customer(customer_id),
    purpose         VARCHAR(40)  NOT NULL,  -- ACCOUNT_SERVICING | MARKETING_EMAIL | ANALYTICS | THIRD_PARTY_SHARING | CREDIT_BUREAU
    granted         BOOLEAN      NOT NULL,
    consent_type    VARCHAR(10)  NOT NULL,  -- EXPRESS | IMPLIED
    capture_channel VARCHAR(20)  NOT NULL,  -- BRANCH | ONLINE | MOBILE | PHONE
    captured_at     TIMESTAMP    NOT NULL,
    withdrawn_at    TIMESTAMP
);

CREATE TABLE core.account (
    account_id      BIGSERIAL PRIMARY KEY,
    customer_id     BIGINT       NOT NULL REFERENCES core.customer(customer_id),
    branch_id       INT          NOT NULL REFERENCES core.branch(branch_id),
    account_number  VARCHAR(12)  NOT NULL UNIQUE,
    account_type    VARCHAR(20)  NOT NULL,  -- CHEQUING | SAVINGS | TFSA | RRSP | CREDIT_CARD | MORTGAGE
    currency        CHAR(3)      NOT NULL DEFAULT 'CAD',
    current_balance NUMERIC(14,2) NOT NULL,
    account_status  VARCHAR(10)  NOT NULL,
    opened_at       TIMESTAMP    NOT NULL,
    closed_at       TIMESTAMP
);

CREATE TABLE core.card (
    card_id         BIGSERIAL PRIMARY KEY,
    account_id      BIGINT       NOT NULL REFERENCES core.account(account_id),
    card_number     VARCHAR(19)  NOT NULL,   -- legacy: full PAN still stored
    expiry_month    SMALLINT     NOT NULL,
    expiry_year     SMALLINT     NOT NULL,
    cvv             CHAR(3),                 -- legacy: should never be stored
    card_status     VARCHAR(10)  NOT NULL
);

CREATE TABLE core.transaction (
    transaction_id  BIGSERIAL PRIMARY KEY,
    account_id      BIGINT       NOT NULL REFERENCES core.account(account_id),
    txn_timestamp   TIMESTAMP    NOT NULL,
    amount          NUMERIC(14,2) NOT NULL,
    txn_type        VARCHAR(20)  NOT NULL,   -- DEBIT | CREDIT | CASH_DEPOSIT | CASH_WITHDRAWAL | E_TRANSFER | BILL_PAYMENT
    channel         VARCHAR(20)  NOT NULL,   -- BRANCH | ATM | ONLINE | MOBILE | POS
    merchant_name   VARCHAR(80),
    merchant_category VARCHAR(40),
    counterparty_email VARCHAR(120),         -- e-Transfer recipient
    client_ip       VARCHAR(45),
    memo            VARCHAR(140)
);

-- ---------------------------------------------------------------- kyc
CREATE TABLE kyc.identity_document (
    document_id     BIGSERIAL PRIMARY KEY,
    customer_id     BIGINT       NOT NULL REFERENCES core.customer(customer_id),
    document_type   VARCHAR(20)  NOT NULL,   -- PASSPORT | DRIVERS_LICENCE
    document_number VARCHAR(20)  NOT NULL,
    issuing_jurisdiction VARCHAR(20) NOT NULL,
    expiry_date     DATE         NOT NULL,
    verified_at     TIMESTAMP    NOT NULL,
    verified_by_employee VARCHAR(60) NOT NULL
);

-- ---------------------------------------------------------------- ops
-- Free-text notes typed by contact-centre agents (unstructured PI).
CREATE TABLE ops.support_ticket (
    ticket_id       BIGSERIAL PRIMARY KEY,
    customer_id     BIGINT REFERENCES core.customer(customer_id),
    opened_at       TIMESTAMP NOT NULL,
    category        VARCHAR(30) NOT NULL,
    agent_notes     TEXT
);

-- Legacy CSV import from an acquired credit union; columns were never renamed.
-- Ground truth: fld_01 = name, fld_02 = SIN, fld_03 = postal code, fld_04 = loyalty points.
CREATE TABLE ops.legacy_member_import (
    import_row_id   BIGSERIAL PRIMARY KEY,
    fld_01          VARCHAR(120),
    fld_02          VARCHAR(20),
    fld_03          VARCHAR(10),
    fld_04          VARCHAR(20),
    imported_at     TIMESTAMP NOT NULL
);

-- Non-personal reference data (negative control for classification).
CREATE TABLE ops.fx_rate (
    rate_date       DATE NOT NULL,
    currency_pair   CHAR(7) NOT NULL,
    rate            NUMERIC(12,6) NOT NULL,
    PRIMARY KEY (rate_date, currency_pair)
);

COMMENT ON TABLE core.customer IS 'Retail banking customers (system of record).';
COMMENT ON TABLE core.transaction IS 'Posted account transactions.';
